-- FRESH INSTALL defaults: 12 products / 76 variants. Safe for a new Supabase project.
-- ON CONFLICT DO NOTHING preserves admin price edits if inadvertently run again.
begin;
on conflict(id) do nothing;
on conflict(product_id,name) do nothing;
commit;
select (select count(*) from public.products) products,(select count(*) from public.product_variants) variants;